test("branch selection uses exact ownership, not name prefixes or untagged status", () => {
  const resources = [
    ...FIXTURE,
    res("old", "volume", null),
    res("next", "volume", null, [], "stk-feat-a-v2"),
    res("tag-only", "volume", "feat-a"),
  ];
  resources.find((r) => r.id === "old")!.name = "feat-a-old";
  resources.find((r) => r.id === "next")!.name = "feat-a-v2-boot";
  const ids = buildPlan(resources, "feat-a").steps.map((s) => s.id).sort();
  assert.deepEqual(ids, ["i-a", "net-a", "sub-a", "tag-only", "vol-a"]);
});

test("project scope retains stack selection and explicitly includes name matches", () => {
  const legacy = res("legacy", "volume", null);
  legacy.name = "feat-a-legacy";
  assert.deepEqual(buildPlan([...FIXTURE, legacy], "feat-a", "project").steps.map((s) => s.id).sort(),
    ["i-a", "legacy", "net-a", "sub-a", "vol-a"]);
});

test("plan reports external dependents without selecting them", () => {
  const external = res("external", "snapshot", "feat-b", ["vol-a"]);
  const plan = buildPlan([...FIXTURE, external], "feat-a");
  assert.deepEqual(plan.blocked, [{ id: "vol-a", dependents: ["external"] }]);
  assert.ok(!plan.steps.some((s) => s.id === "external"));
});

test("deletion order handles shared dependencies in arbitrary listing order without mutating input", () => {
  const graph = [
    res("root", "network", "feat-a"),
    res("left", "subnet", "feat-a", ["root"]),
    res("right", "subnet", "feat-a", ["root"]),
    res("leaf", "instance", "feat-a", ["left", "right", "outside"]),
    res("peer", "instance", "feat-a", ["left", "left"]),
  ];
  for (const resources of [graph, [...graph].reverse(), [graph[2], graph[4], graph[0], graph[3], graph[1]]]) {
    const before = structuredClone(resources);
    const order = buildPlan(resources, "feat-a").steps.map((s) => s.id);
    assert.equal(new Set(order).size, graph.length);
    for (const r of graph) {
      for (const dep of r.depends_on.filter((id) => id !== "outside")) {
        assert.ok(order.indexOf(r.id) < order.indexOf(dep), `${r.id} must precede ${dep}: ${order}`);
      }
    }
    assert.deepEqual(resources, before);
  }
});

test("dependency cycles fail planning instead of producing an unsafe partial order", () => {
  assert.throws(() => buildPlan([
    res("a", "volume", "feat-a", ["b"]),
    res("b", "volume", "feat-a", ["a"]),
    res("independent", "volume", "feat-a"),
  ], "feat-a"), /dependency cycle/);
  assert.throws(() => buildPlan([res("self", "volume", "feat-a", ["self"])], "feat-a"), /dependency cycle/);
});

test("empty and already torn-down branches have empty plans", () => {
  assert.deepEqual(buildPlan([], "feat-a"), { branch: "feat-a", steps: [], blocked: [] });
  assert.deepEqual(buildPlan(FIXTURE, "absent"), { branch: "absent", steps: [], blocked: [] });
});
